#include<iostream>
using namespace std;

struct LNode {
    int data;
    LNode* next;
    LNode(int x = 0) : data(x), next(nullptr) {}
};

using linklist = LNode*;

bool initList(linklist &L) {
    L = new LNode();
    return true;
}

int main() {
    linklist L;
    initList(L);  // 创建头结点

    // 1. 在堆上创建三个实实在在的节点
    LNode* node1 = new LNode(2);
    LNode* node2 = new LNode(5);
    LNode* node3 = new LNode(8);

    // 2. 把 next 指针"指向"下一个节点（这就是链接！）
    node1->next = node2;  // 把 node2 的地址 赋值给 node1 的 next
    node2->next = node3;  // 把 node3 的地址 赋值给 node2 的 next
    L->next = node1;      // 头结点指向 node1

    // 3. 【关键】打印地址，让你亲眼看到 next 存了什么！
    cout << "=== 打印节点地址和 next 指针的值 ===" << endl;

    // 打印头结点
    cout << "头结点 L 的地址: " << L << endl;
    cout << "头结点 L->next 保存的值: " << L->next << " (指向 node1)" << endl << endl;

    // 打印 node1
    cout << "节点1 (data=2) 自己的地址: " << node1 << endl;
    cout << "节点1 node1->next 保存的值: " << node1->next << " (这就是 node2 的地址)" << endl << endl;

    // 打印 node2
    cout << "节点2 (data=5) 自己的地址: " << node2 << endl;
    cout << "节点2 node2->next 保存的值: " << node2->next << " (这就是 node3 的地址)" << endl << endl;

    // 打印 node3
    cout << "节点3 (data=8) 自己的地址: " << node3 << endl;
    cout << "节点3 node3->next 保存的值: " << node3->next << " (nullptr，表示结束)" << endl << endl;

    // 4. 顺便用循环遍历，对比一下 p 的变化
    cout << "=== 遍历时 p 的变化 ===" << endl;
    LNode* p = L->next; // p 刚开始指向 node1
    int count = 1;
    while (p != nullptr) {
        cout << "第 " << count << " 次循环，p 里面存的地址是: " << p << " (当前 data=" << p->data << ")" << endl;
        p = p->next; // 这一步，就是把 node 里的 next 地址取出来，放进 p 里
        count++;
    }

    // 释放内存（好习惯）
    delete node1; delete node2; delete node3; delete L;
    return 0;
}

