// 1. 定义节点
typedef struct LNode
{
    int data;           // 数据域
    struct LNode *next; // 指针域

}LNode, *LinkList;
// 2. 初始化链表（创建头结点）
bool InitList(LinkList &L)
{
    L = new LNode;  // 创建头结点

    if(L == NULL)
        return false;

    L->next = NULL; // 头结点后面暂时没有节点

    return true;
}
// 3. 头插法插入元素
// 将x插入到链表最前面

bool InsertHead(LinkList L, int x)
{
    LNode *p = new LNode;

    if(p == NULL)
        return false;


    p->data = x;


    // 关键两步
    p->next = L->next;
    L->next = p;


    return true;
}



// 4. 指定位置插入
// 在第i个位置插入x

bool Insert(LinkList L, int i, int x)
{
    LNode *p = L;

    int j = 0;


    // 找到第i-1个节点
    while(p != NULL && j < i-1)
    {
        p = p->next;
        j++;
    }


    if(p == NULL)
        return false;


    LNode *s = new LNode;

    s->data = x;


    // 修改指针
    s->next = p->next;
    p->next = s;


    return true;
}



// 5. 删除第i个节点

bool Delete(LinkList L, int i)
{
    LNode *p = L;

    int j = 0;


    // 找到第i-1个节点
    while(p != NULL && j < i-1)
    {
        p = p->next;
        j++;
    }


    if(p == NULL || p->next == NULL)
        return false;


    // 保存要删除的节点
    LNode *q = p->next;


    // 前一个节点绕过它
    p->next = q->next;


    delete q;


    return true;
}



// 6. 遍历链表

void Print(LinkList L)
{
    LNode *p = L->next; // 跳过头结点


    while(p != NULL)
    {
        cout << p->data << " ";

        p=p->next;
    }

    cout<<endl;
}




